actions.script:
salesList = []
boolean __d = ec.artifactExecution.disableAuthz()
try {
    def ef = ec.entity.find("zenith.erp.pos.PosTransaction")
        .condition("statusId", "PtCompleted").condition("transactionType", "Sale")
    if (activeOrg && activeOrg != '_NA_') ef.condition("organizationPartyId", activeOrg)
    def bn = ec.web.parameters.transactionNumber?.trim()
    if (bn) ef.condition("transactionNumber", "like", "%" + bn + "%")
    def dFrom = ec.web.parameters.entryDate_from?.trim()
    def dThru = ec.web.parameters.entryDate_thru?.trim()
    try {
        if (dFrom) ef.condition("entryDate", ">=", ec.l10n.parseTimestamp(dFrom + " 00:00:00", "yyyy-MM-dd HH:mm:ss"))
        if (dThru) ef.condition("entryDate", "<=", ec.l10n.parseTimestamp(dThru + " 23:59:59", "yyyy-MM-dd HH:mm:ss"))
    } catch (Exception e) { /* ignore unparseable date filter */ }
    def txnList = ef.orderBy("-entryDate").limit(500).list()
for (def txn : txnList) {
    def pays = ec.entity.find("zenith.erp.pos.PosPayment")
        .condition("transactionId", txn.transactionId).orderBy("paymentDate").list()
    def payMethods, paySummary, closed = txn.completedDate
    if (pays) {
        payMethods = pays.collect { it.paymentMethod ?: 'Other' }.unique().join(', ')
        paySummary = pays.collect { (it.paymentMethod ?: 'Other') + ' ₹' + ec.l10n.format(it.amount ?: 0, '#,##,##0.00') }.join('  +  ')
        if (!closed) { def pd = pays.collect { it.paymentDate }.findAll { it }; if (pd) closed = pd.max() }
    } else if (txn.isCredit == 'Y') {
        payMethods = 'Credit'
        paySummary = 'Credit (unpaid)'
    } else {
        payMethods = ''
        paySummary = ''
    }
    if (!closed) closed = txn.lastUpdatedStamp
    salesList.add([
        transactionId: txn.transactionId,
        linkedInvoiceId: txn.linkedInvoiceId,
        billNo: txn.transactionNumber ?: txn.transactionId,
        customerDisplay: txn.customerName ?: 'Walk-in',
        amount: txn.payableAmount ?: txn.grandTotal ?: 0,
        saleStarted: txn.entryDate,
        saleClosed: closed,
        payMethods: payMethods,
        paySummary: paySummary,
        isCredit: txn.isCredit
    ])
}
} finally { if (!__d) ec.artifactExecution.enableAuthz() }
